pub fn solve(n: i8, k: i8) -> i8 {
    // Compute the nonnegative remainder of n divided by k
    let r = n % k;
    // Since n >= 0 and k > 0, r is already in [0, k)
    // The minimal distance to the nearest multiple is min(r, k - r)
    let dist = std::cmp::min(r, k - r);
    dist
}

